messages.content:
Execute 'FGBR_OC.ipynb'.  Save the results in html format in ../results. For all the runs, disable the cell execution timeout and allow errors.
Questions:
{
  "q1": "Report the best test R^2 value for c = 1.0.",
  "q2": "Report the best test RMSE value for c = 1.0."
}

arguments.command:
cd /results && python - <<'PY'
import nbformat, re, json
nb = nbformat.read('FGBR_OC_executed.ipynb', as_version=4)
for i, cell in enumerate(nb.cells):
    if cell.cell_type=='code':
        src = cell.source
        if 'c = 1.0' in src or 'best test' in src.lower() or 'R^2' in src or 'RMSE' in src:
            print('\nCELL', i)
            print(src)
            outs = cell.get('outputs', [])
            for o in outs:
                if 'text' in o:
                    print('OUTPUT:', o['text'])
                if 'data' in o and 'text/plain' in o['data']:
                    print('DATA:', o['data']['text/plain'])
PY

cd /results && python - <<'PY'
import nbformat
nb=nbformat.read('FGBR_OC_executed.ipynb', as_version=4)
for i,cell in enumerate(nb.cells):
    if cell.cell_type=='code' and cell.outputs:
        print('CELL',i,'outputs',len(cell.outputs))
        for o in cell.outputs:
            if 'text' in o:
                print(o['text'])
            elif o.output_type=='stream':
                print(o.get('text',''))
            elif o.output_type=='error':
                print('ERROR', o.ename, o.evalue)
PY

cd /results && python - <<'PY'
import nbformat, re
nb=nbformat.read('FGBR_OC_executed.ipynb', as_version=4)
for i,cell in enumerate(nb.cells):
    if cell.cell_type=='code':
        text=''
        for o in cell.outputs:
            if o.output_type=='stream': text += o.text
            elif o.output_type=='execute_result': text += o.data.get('text/plain','')
        if 'c = 1.0' in text or 'c = 1' in text:
            print('CELL',i)
            print(text)
PY
